"use strict";$(document).ready(function(){var n=$("#Id").val();$(".viewhistoryjobgrade").click(function(){var t="/employee/ViewHistoryJobGrade/"+n;$.get(t,function(n){$("#dialog-show-history-jobgrade").html(n);$("#dialog-show-history-jobgrade").dialog({modal:!0,height:"auto",width:"auto",title:"Job Grade History",show:{effect:"fade",duration:300},hide:{effect:"fade",duration:200}})})})});